#!/usr/bin/env python3
"""rules_registry.py - ANTIPATTERNS registry ported from
    github.com/pbakaus/impeccable @ c3bb418
    (crates/live/assets/antipatterns.json, 62 rules).
    scope: static = implemented here; browser = skipped by the static
    linter; designsys = needs DESIGN.md tokens (not wired yet).
"""

ANTIPATTERNS = [
    {"id": "side-tab", "category": "slop", "name": "Side-tab accent border", "scope": "static", "description": "Thick colored border on one side of a card â€” the most recognizable tell of AI-generated UIs. Use a subtler accent or remove it entirely."},
    {"id": "border-accent-on-rounded", "category": "slop", "name": "Border accent on rounded element", "scope": "static", "description": "Thick accent border on a rounded card â€” the border clashes with the rounded corners. Remove the border or the border-radius."},
    {"id": "overused-font", "category": "slop", "name": "Overused font", "scope": "static", "description": "Inter, Roboto, Fraunces, Geist, Plus Jakarta Sans, and Space Grotesk are used on so many sites they no longer feel distinctive. Each new wave of AI-generated UIs converges on the same handful of faces. Choose a face that gives your interface personality."},
    {"id": "flat-type-hierarchy", "category": "slop", "name": "Flat type hierarchy", "scope": "static", "description": "Dominant heading and body roles are separated by less than 1.25Ã— at every step, leaving the size hierarchy flat. Add at least one stronger size step."},
    {"id": "gradient-text", "category": "slop", "name": "Gradient text", "scope": "static", "description": "Gradient text is decorative rather than meaningful â€” a common AI tell, especially on headings and metrics. Use solid colors for text."},
    {"id": "ai-color-palette", "category": "slop", "name": "AI color palette", "scope": "static", "description": "Purple/violet gradients and cyan-on-dark are the most recognizable tells of AI-generated UIs. A gradient in one of those hues is the tell on its own; flat neon ink on a dark ground is charged once a second tell hue joins it. Choose a distinctive, intentional palette."},
    {"id": "cream-palette", "category": "slop", "name": "Cream / beige palette", "scope": "static", "description": "A warm cream or beige page background has become the default \"tasteful\" AI surface, reached for by reflex. Choose a background that comes from a deliberate palette, not the safe warm off-white."},
    {"id": "nested-cards", "category": "slop", "name": "Nested cards", "scope": "static", "description": "Cards inside cards create visual noise and excessive depth. Flatten the hierarchy â€” use spacing, typography, and dividers instead of nesting containers."},
    {"id": "monotonous-spacing", "category": "slop", "name": "Monotonous spacing", "scope": "static", "description": "The same spacing value used everywhere â€” no rhythm, no variation. Use tight groupings for related items and generous separations between sections."},
    {"id": "bounce-easing", "category": "slop", "name": "Bounce or elastic easing", "scope": "static", "description": "Bounce and elastic easing feel dated and tacky. Real objects decelerate smoothly â€” use exponential easing (ease-out-quart/quint/expo) instead."},
    {"id": "pulsing-dot", "category": "slop", "name": "Pulsing status dot", "scope": "static", "description": "Small pulsing status dots simulate liveness decoratively. Reserve pulse animation for indicators tied to genuinely live, changing data; a static indicator with clear labeling is honest and calmer."},
    {"id": "blinking-cursor", "category": "slop", "name": "Decorative blinking cursor", "scope": "static", "description": "A blinking text cursor animated into a hero or landing section simulates typing where no input exists. It borrows the dev-tool aesthetic as decoration. Real editable fields draw their own caret; anywhere else, let the composition hold attention without a fake prompt."},
    {"id": "shape-assembled-illustration", "category": "slop", "name": "Shape-assembled illustration", "scope": "browser", "description": "A large inline SVG that builds a pictorial scene from a pile of primitive shapes reads as placeholder clip art, not illustration. Icons, logos, and data graphics are fine at their scale; a hero-sized visual deserves real artwork, a photograph, or a deliberately drawn graphic."},
    {"id": "organic-clip-path", "category": "quality", "name": "Organic contour drawn as clip-path", "scope": "browser", "description": "A clip-path polygon with many arbitrary vertices, or a curved clip-path path(), is CSS approximating a torn edge, blob, or silhouette. It reads as the cheap version of the effect and is usually a produced or photographic material replaced with code. Derive an alpha matte from the real image, or ship the shape as a cut-out raster; keep clip-path for geometry (cut corners, diagonals, hexagons)."},
    {"id": "buried-raster", "category": "quality", "name": "Raster buried under a wash or opacity", "scope": "browser", "description": "A background image under a near-opaque gradient wash, or a raster on an element at near-zero opacity, never reaches the screen: the page shows the wash, and the produced texture or photo ships as a compliance token. Let the material show (a tint under 0.9 alpha, a blend mode, an opacity you can see) or remove the file."},
    {"id": "hard-offset-shadow", "category": "quality", "name": "Hard offset shadow", "scope": "static", "description": "A visible, unblurred shadow displaced by at least 4px can belong to an intentional neobrutalist direction. Check whether it fits the intended design; this is a review prompt, not evidence of AI authorship or a request to remove it automatically. Waive intentional uses with data-impeccable-ignore=\"hard-offset-shadow\"."},
    {"id": "dark-glow", "category": "slop", "name": "Glowing shadow accents", "scope": "static", "description": "Colored glow shadows â€” a zero-offset chromatic halo (box- or text-shadow) on any background, or any colored blurred shadow on a dark background â€” are the default \"cool\" look of AI-generated UIs. Use neutral elevation shadows and subtle, purposeful lighting instead."},
    {"id": "radial-halo", "category": "slop", "name": "Radial-gradient background halo", "scope": "static", "description": "A chromatic radial-gradient wash â€” saturated at the center, fading to transparent â€” used as a decorative background glow on a dark page. Same tell as glowing shadows, drawn with a gradient instead of a shadow. Ground the surface with a solid or subtly shifted background instead."},
    {"id": "radial-spotlight-glow", "category": "slop", "name": "Decorative radial spotlight glow", "scope": "static", "description": "An accent-colored radial gradient fading to transparent, dropped behind a hero or section as a \"spotlight\" and bright enough against that surface to read as a cloud floating over the copy. It is a reflex AI decoration â€” the translucent cousin of the saturated radial halo. Let the surface stand on its own, or light the composition with a deliberate material accent rather than a floating colored haze."},
    {"id": "marquee", "category": "slop", "name": "Auto-scrolling marquee", "scope": "static", "description": "Continuously auto-scrolling content demands attention it has not earned and hides half its content at any moment. Reserve motion for content that changes; let readers move at their own pace."},
    {"id": "icon-tile-stack", "category": "slop", "name": "Icon tile stacked above heading", "scope": "static", "description": "A small rounded-square icon container above a heading is the universal AI feature-card template â€” every generator outputs this exact shape. Try a side-by-side icon and heading, or let the icon sit in flow without its own container."},
    {"id": "italic-serif-display", "category": "slop", "name": "Italic serif display headline", "scope": "static", "description": "Oversized italic serif (Fraunces, Recoleta, Playfair, Newsreader-italic) as the primary hero headline reads as taste in isolation but has become the universal AI-startup landing page hero. Set roman, or move to a non-serif display face. Editorial / magazine register may legitimately want this â€” judge by context."},
    {"id": "hero-eyebrow-chip", "category": "slop", "name": "Hero eyebrow / pill chip", "scope": "static", "description": "A tiny uppercase letter-spaced label sitting immediately above an oversized hero headline â€” or the same shape rendered as a pill chip â€” is now the default AI SaaS hero. Drop the eyebrow, integrate the kicker into the headline, or run it as a navigation breadcrumb instead."},
    {"id": "kicker-above-heading", "category": "slop", "name": "Kicker / eyebrow label above heading", "scope": "static", "description": "A tiny tracked uppercase or small-caps label sitting as its own block directly above a heading is banned outright, repeated or not. Generated kickers never earn their place: the heading carries its own weight. Delete the label and let the heading speak; if the words matter, work them into the heading or the body."},
    {"id": "numbered-section-labels", "category": "slop", "name": "Tiny numbered section labels", "scope": "static", "description": "Small numeric index labels riding next to section headings, repeated section after section, are AI editorial scaffolding â€” a page numbering its own chapters instead of earning structure. Let hierarchy, content, and rhythm carry the sequence."},
    {"id": "em-dash-overuse", "category": "slop", "name": "Em-dash overuse", "scope": "static", "description": "Em-dash saturation in body copy is an AI cadence tell. Advisory only: humans use em-dashes legitimately, so this fires only on saturation â€” at least 8 em-dashes (â€” or --) at a density near one per 500 characters of body text â€” never on a long article that uses a few. Prefer commas, colons, periods, or parentheses."},
    {"id": "marketing-buzzword", "category": "slop", "name": "Marketing buzzword", "scope": "static", "description": "Generic SaaS phrases (streamline / empower / supercharge / world-class / enterprise-grade / next-generation / cutting-edge / etc) are instant AI tells. Pick a specific verb and noun that says what the product literally does."},
    {"id": "aphoristic-cadence", "category": "slop", "name": "Aphoristic-cadence copy", "scope": "static", "description": "Three or more sections landing on a short rebuttal sentence (\"X. No Y.\" / \"X. Just Y.\") or a manufactured-contrast aphorism (\"Not a feature. A platform.\") reads as AI cadence, not voice. Once is fine; the pattern is the tell."},
    {"id": "oversized-h1", "category": "slop", "name": "Oversized hero headline", "scope": "static", "description": "A full-sentence headline set at display size ends up dominating the viewport, leaving no room for anything else above the fold. A punchy one- or two-word headline at that size is fine â€” the problem is a long headline blown up too large. Set long headlines smaller, or tighten the copy."},
    {"id": "extreme-negative-tracking", "category": "slop", "name": "Crushed letter spacing", "scope": "static", "description": "Letter-spacing pulled tighter than the point where characters keep their own shapes costs legibility. Tighten display type optically, not destructively."},
    {"id": "broken-image", "category": "quality", "name": "Broken or placeholder image", "scope": "static", "description": "<img> tags with empty src, missing src, or placeholder values ship as broken-image boxes. Use real images, generated assets, or remove the tag."},
    {"id": "script-error", "category": "quality", "name": "Uncaught script error on load", "scope": "browser", "description": "A script threw an uncaught exception or failed to parse while the page loaded. Broken JavaScript silently kills reveals, interactions, and dynamic content, and can leave most of a page invisible. Fix the error before judging anything else."},
    {"id": "content-hidden-at-rest", "category": "quality", "name": "Content invisible at rest", "scope": "browser", "description": "A large share of the page text sits at opacity 0 or visibility hidden even after every reveal handler had a chance to run. This is the failed-reveal signature: the content shipped but never becomes visible. Make content visible by default and let JavaScript enhance its entrance instead of gating its existence."},
    {"id": "edge-flush-cards", "category": "quality", "name": "Cards flush against the scroller edge", "scope": "browser", "description": "Cards inside a horizontal scroller or tab panel sit flush against the container edge at rest while keeping a gutter on the other side, so their edges and rounded corners get cut off. Usually the panel is sized wider than its clip box. Keep a consistent inset on both sides."},
    {"id": "text-occlusion", "category": "quality", "name": "Text occluded by an overlapping element", "scope": "browser", "description": "Text is painted under an opaque element or a second text run, so part of it cannot be read. A decorative box, a stacked layer, or an inline element with leaked padding lands on the words instead of beside them. Give overlapping layers room, or move the text out from under the layer above it."},
    {"id": "first-viewport-column-overflow", "category": "quality", "name": "One column stretches the first viewport", "scope": "browser", "description": "A multi-column opening section lets one column run far past the fold while its sibling fits in a single viewport, so the short column floats in dead space and the fold falls deep inside one section. Balance the columns, cap the tall one, or let the long content flow below the opening row."},
    {"id": "gray-on-color", "category": "quality", "name": "Gray text on colored background", "scope": "static", "description": "Gray text looks washed out on colored backgrounds. Use a darker shade of the background color instead, or white/near-white for contrast."},
    {"id": "low-contrast", "category": "quality", "name": "Low contrast text", "scope": "static", "description": "Text does not meet WCAG AA contrast requirements (4.5:1 for body, 3:1 for large text). Increase the contrast between text and background."},
    {"id": "line-length", "category": "quality", "name": "Line length too long", "scope": "static", "description": "Text lines wider than ~80 characters are hard to read. The eye loses its place tracking back to the start of the next line, so it is measured on the lines that rendered and charged when more than one of them runs long. Add a max-width (65ch to 75ch) to text containers."},
    {"id": "cramped-padding", "category": "quality", "name": "Cramped padding", "scope": "static", "description": "Text is too close to the edge of its container. Two shapes: (1) an element with its own text where the space between the rendered text and the border box is too small for the font size, and (2) a wrapper whose children's text lands flush against a visible boundary (border, outline, or non-transparent background) with nothing to inset it. Add at least 8px (ideally 12â€“16px) of space inside bordered, outlined, or colored containers."},
    {"id": "body-text-viewport-edge", "category": "quality", "name": "Body text touching viewport edge", "scope": "browser", "description": "Body paragraphs render flush against the left or right viewport edge with no container providing horizontal padding: closer than 16px, or 12px on viewports 480px wide or narrower. Wrap content in a container with at least 16px (ideally 24-32px) of horizontal padding, or apply max-width with mx-auto. Body text that runs past the viewport edge is reported once per page as overflow, naming the widest element: constrain that element's width instead of adding padding."},
    {"id": "tight-leading", "category": "quality", "name": "Tight line height", "scope": "static", "description": "Line height below 1.3x the font size makes multi-line text hard to read. Use 1.5 to 1.7 for body text so lines have room to breathe."},
    {"id": "skipped-heading", "category": "quality", "name": "Skipped heading level", "scope": "static", "description": "Heading levels should not skip (e.g. h1 then h3 with no h2). Screen readers use heading hierarchy for navigation. Skipping levels breaks the document outline."},
    {"id": "heading-rhythm", "category": "quality", "name": "Heading crowded against the previous block", "scope": "browser", "description": "A heading binds to the content it introduces, so the rendered space above it should exceed the space below it. When headings across a page sit as close or closer to the block above than to their own content, every section reads as if it captions the previous one. Open up the space above each heading."},
    {"id": "justified-text", "category": "quality", "name": "Justified text", "scope": "static", "description": "In a column this narrow, justifying without hyphenation stretches the word spaces until vertical rivers of white run down the block. Use text-align: left, widen the measure, or enable hyphens: auto if you must justify. Scripts that justify on a character grid or by elongating glyphs, such as CJK, Thai and Arabic, are not affected and are not reported."},
    {"id": "straggler", "category": "quality", "name": "Straggler", "scope": "browser", "description": "The last line of this paragraph holds one word, which leaves a hole under the block. Set text-wrap: pretty on body copy (Chrome, Safari) to pull a word down beside it. Where a browser ignores it, edit the last sentence or bind the last two words with a no-break space. Keep it if the break is intended."},
    {"id": "unbalanced-heading", "category": "quality", "name": "Unbalanced heading", "scope": "browser", "description": "This heading wraps with its last line far shorter than the line above, often one word alone. Set text-wrap: balance on headings so the lines come out near even, or rewrite it to fit. Keep it if the break carries weight on purpose."},
    {"id": "tiny-text", "category": "quality", "name": "Tiny body text", "scope": "static", "description": "Body text below 12px is hard to read, especially on high-DPI screens. Use at least 14px for body content, 16px is ideal."},
    {"id": "undersized-ui-text", "category": "quality", "name": "Undersized functional text", "scope": "static", "description": "Interactive and content-bearing UI text (links, buttons, nav items, labels, table cells, meta rows, timecodes) below 11px is a legibility failure, not a style choice. WCAG sets no absolute pixel floor, but functional text under 11px is a defensible quality bar: it fails on high-DPI and small viewports and it degrades tap and read targets. The 11px floor holds even inside a footer; only non-interactive legal smallprint gets the softer 10px floor. Being ON the DESIGN.md size ramp does not exempt a value here: adding 8px to the ramp launders the token but not the legibility problem, and that is exactly the escape hatch this rule closes. Exempts sup/sub, visually-hidden (sr-only) text, and code/terminal contexts. Decorative letterspaced micro-labels are still functional and stay in scope."},
    {"id": "all-caps-body", "category": "quality", "name": "All-caps body text", "scope": "static", "description": "Long passages in uppercase are hard to read. We recognize words by shape (ascenders and descenders), which all-caps removes. Reserve uppercase for short labels and headings. Only a run that reads as a sentence counts: 80 characters or more of an element's own text. Buttons, nav items, kickers and eyebrows set in caps are a convention and stay silent."},
    {"id": "wide-tracking", "category": "quality", "name": "Wide letter spacing on body text", "scope": "static", "description": "Letter spacing above 0.05em on body text disrupts natural character groupings and slows reading. Reserve wide tracking for short uppercase labels only."},
    {"id": "text-overflow", "category": "quality", "name": "Content overflowing its container", "scope": "browser", "description": "Content renders wider than its container and the spill does harm: a clipping ancestor cuts it off, it runs into another box, or it reaches the viewport edge. Let text wrap, constrain widths, or give the region a deliberate scroll affordance."},
    {"id": "repeated-container-text", "category": "quality", "name": "Same text repeated inside one container", "scope": "static", "description": "The same literal text rendered three or more times in structurally different spots inside a single card or panel is redundant messaging â€” usually a status or label wired into every slot of a template. Say it once, in the slot where it matters most."},
    {"id": "clipped-overflow-container", "category": "quality", "name": "Positioned child clipped by overflow container", "scope": "browser", "description": "A clipping container (overflow hidden or clip) wrapping an absolutely-positioned child cuts off tooltips, menus, and popovers that need to escape. Let the overflow be visible, or move the positioned layer out of the clip."},
    {"id": "design-system-font", "category": "quality", "name": "Font outside DESIGN.md", "scope": "designsys", "description": "A font is used that is not declared in DESIGN.md typography. Use the documented type system or update DESIGN.md if this is an intentional brand addition."},
    {"id": "design-system-color", "category": "quality", "name": "Color outside DESIGN.md", "scope": "designsys", "description": "A literal color is outside the DESIGN.md palette and sidecar tonal ramps. This may be legitimate, but it should be an intentional design-system addition rather than drift."},
    {"id": "design-system-radius", "category": "quality", "name": "Radius outside DESIGN.md", "scope": "designsys", "description": "A border-radius value is outside the DESIGN.md rounded scale. Use a documented radius token or update the design system if the new shape is intentional."},
    {"id": "design-system-font-size", "category": "quality", "name": "Font size outside DESIGN.md", "scope": "designsys", "description": "A literal font-size is off the type ramp documented in DESIGN.md typography. Use a documented size step or update the design system if the new step is intentional."},
    {"id": "gpt-thin-border-wide-shadow", "category": "slop", "name": "Hairline border with wide shadow", "scope": "static", "description": "Every card of this row wears a hairline border paired with a wide, diffuse shadow, which is a recurring generated-UI signature. One floating panel earns both; a whole row wearing them reads as a default nobody chose. Across the row, commit to one: a defined edge or a soft elevation."},
    {"id": "repeating-stripes-gradient", "category": "slop", "name": "Repeating-gradient stripes", "scope": "static", "description": "Repeating-gradient stripes used as surface decoration are a recurring generated-UI signature. Reach for a deliberate texture or leave the surface plain."},
    {"id": "codex-grid-background", "category": "slop", "name": "Decorative grid-line background", "scope": "static", "description": "A decorative grid or line-field background drawn with hairline linear-gradient layers tiled by a fixed pixel cell is a recurring generated-UI signature. Reserve grid overlays for actual canvas, map, blueprint, or measurement surfaces; elsewhere use product structure or a plain surface."},
    {"id": "theater-slop-phrase", "category": "slop", "name": "Theater framing copy", "scope": "static", "description": "Dismissing something as \"theater\" is a recurring generated-copy tic. Say plainly what the thing does or does not do."},
]
